      "given": "Primary amide $R-CONH_2$ reacting with bromine and sodium hydroxide.",
      "formula": "$R-CONH_2 + Br_2 + 4NaOH \\rightarrow R-NH_2 + Na_2CO_3 + 2NaBr + 2H_2O$",
