    "question": "Q328. (NEET Medium) In the Hofmann bromamide degradation reaction, an amide is converted into a primary amine containing one less carbon atom. The number of moles of $\\text{NaOH}$ and $\\text{Br}_2$ consumed per mole of amide are:",
